#!/usr/bin/env node
// build-composition.mjs
//
// Generates the Hyperframes HTML compositions for a song from the pipeline's
// JSON outputs:
//
//   inputs:
//     songs/<name>/lyrics-fixed.json   [{ text, start, end, type }]
//     songs/<name>/theme.json          ThemeConfig (see README / theme-design skill)
//     songs/<name>/audio.mp3
//     songs/<name>/bg.jpg
//     assets/energy.json               generated by analyze-audio.mjs
//
//   outputs:
//     index.html                       root composition (bg + particles + lyrics + audio)
//     compositions/lyrics.html         word-level karaoke sub-composition
//     assets/audio.mp3, assets/bg.jpg  copied media
//     meta.json                        minimal project metadata
//
// Usage:
//   node scripts/build-composition.mjs --song songs/<name>

import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const WIDTH = 1920;
const HEIGHT = 1080;

const DEFAULTS = {
  fps: 30,
  mood: "energetic",
  genre: "pop",
  energy: 0.7,
  colors: {
    primary: "#ff3366",
    secondary: "#ff9933",
    accent: "#ffcc00",
    background: "#0a0a0a",
    text: "#ffffff",
    textShadow: "rgba(255,51,102,0.8)",
  },
  typography: {
    fontFamily: '"Bebas Neue", "Impact", sans-serif',
    fontSize: 72,
    fontWeight: 800,
    letterSpacing: 4,
    lineHeight: 1.1,
    activeWordScale: 1.15,
    activeWordGlow: "0 0 30px currentColor",
  },
  animation: {
    wordEntrance: "scale-pop",
  },
  particles: {
    count: 120,
    types: ["spark", "glow"],
    sizeRange: [2, 8],
    speedRange: [1, 5],
    opacityRange: [0.3, 0.9],
    colors: ["#ff3366", "#ff9933", "#ffcc00", "#ffffff"],
  },
  background: {
    zoomAmount: 0.12,
    blur: 0,
    brightness: 0.6,
    saturation: 1.4,
    overlayOpacity: 0.3,
  },
};

const ENTRANCE = {
  spring: { ease: "elastic.out(1, 0.45)", y: 18, scale: 0.7 },
  "scale-pop": { ease: "back.out(1.7)", y: 0, scale: 0.5 },
  fade: { ease: "power1.out", y: 0, scale: 1 },
  "slide-up": { ease: "power2.out", y: 26, scale: 1 },
};

const SHAPE_CSS = {
  spark: "p-shape-spark",
  glow: "p-shape-glow",
  bubble: "p-shape-bubble",
  wave: "p-shape-wave",
  geometric: "p-shape-geometric",
};

const SHAPE_REACT = {
  spark: "p-react-bass",
  glow: "p-react-bass",
  bubble: "p-react-mid",
  wave: "p-react-soft",
  geometric: "p-react-bass",
};

const SYSTEM_FONTS = new Set([
  "Georgia",
  "Impact",
  "Arial Black",
  "Segoe UI",
  "Times New Roman",
  "Arial",
  "sans-serif",
  "serif",
  "monospace",
]);

function parseArgs(argv) {
  const args = { song: null, energy: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--song") args.song = argv[++i];
    else if (a === "--energy") args.energy = argv[++i];
  }
  return args;
}

function mergeTheme(t) {
  if (!t || typeof t !== "object") return structuredClone(DEFAULTS);
  const out = structuredClone(DEFAULTS);
  for (const k of ["fps", "mood", "genre", "energy"]) if (t[k] != null) out[k] = t[k];
  for (const k of ["colors", "typography", "animation", "particles", "background"]) {
    if (t[k] && typeof t[k] === "object") out[k] = { ...out[k], ...t[k] };
  }
  return out;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashSeed(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function hexToRgba(hex, alpha) {
  const h = (hex || "#ffffff").replace("#", "");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function googleFontLink(fontFamily, weight) {
  const m = fontFamily.match(/"([^"]+)"/);
  const name = m ? m[1] : null;
  if (!name || SYSTEM_FONTS.has(name)) return "";
  const fam = name.replace(/\s+/g, "+");
  return (
    `<link href="https://fonts.googleapis.com/css2?family=${fam}:wght@${weight}&display=swap" rel="stylesheet" />`
  );
}

function escCss(s) {
  return String(s).replace(/</g, "\\3C ").replace(/"/g, '\\"');
}

function buildChunks(words, maxWords = 12, gapThreshold = 0.9) {
  const chunks = [];
  let cur = [];
  for (const w of words) {
    const prev = cur[cur.length - 1];
    if (cur.length && (cur.length >= maxWords || w.start - prev.end > gapThreshold)) {
      chunks.push(cur);
      cur = [];
    }
    cur.push(w);
  }
  if (cur.length) chunks.push(cur);
  return chunks;
}

function chunkWindows(chunks, dur) {
  return chunks.map((chunk, i) => {
    const next = chunks[i + 1];
    const start = Math.max(0, chunk[0].start - 0.25);
    const end = next
      ? Math.min(chunk[chunk.length - 1].end + 0.45, next[0].start + 0.05)
      : Math.min(dur, chunk[chunk.length - 1].end + 0.75);
    return { start, end };
  });
}

function buildParticles(theme, seedStr) {
  const cfg = theme.particles;
  const rand = mulberry32(hashSeed(seedStr));
  const count = Math.max(24, Math.min(140, cfg.count ?? DEFAULTS.particles.count));
  const [minSize, maxSize] = cfg.sizeRange ?? [2, 8];
  const [minSpd, maxSpd] = cfg.speedRange ?? [1, 5];
  const [minOp, maxOp] = cfg.opacityRange ?? [0.3, 0.9];
  const colors = cfg.colors ?? [DEFAULTS.colors.primary];
  const types = cfg.types ?? ["spark", "glow"];
  const out = [];
  for (let i = 0; i < count; i++) {
    const shape = types[Math.floor(rand() * types.length)] || "spark";
    const color = colors[Math.floor(rand() * colors.length)] || "#ffffff";
    const size = minSize + rand() * (maxSize - minSize);
    const speed = minSpd + rand() * (maxSpd - minSpd);
    const rot = shape === "geometric" ? (rand() * 2 - 1) * 540 : 0;
    out.push({
      i,
      x: Math.round(rand() * WIDTH),
      y: Math.round(rand() * HEIGHT),
      size: +size.toFixed(1),
      color,
      halo: hexToRgba(color, 0.45),
      opacity: +(minOp + rand() * (maxOp - minOp)).toFixed(2),
      glow: Math.round(size * 3),
      shapeClass: SHAPE_CSS[shape] || "p-shape-glow",
      reactClass: SHAPE_REACT[shape] || "p-react-bass",
      dx: Math.round((rand() - 0.5) * speed * 90),
      dy: Math.round((rand() - 0.5) * speed * 60 - 40),
      rot,
      geometric: shape === "geometric",
    });
  }
  return out;
}

async function main() {
  const { song, energy } = parseArgs(process.argv.slice(2));
  if (!song) {
    console.error("Usage: node scripts/build-composition.mjs --song songs/<name>");
    process.exit(1);
  }

  const songDir = path.resolve(ROOT, song);
  const lyricsPath = path.join(songDir, "lyrics-fixed.json");
  const themePath = path.join(songDir, "theme.json");
  const audioSrc = path.join(songDir, "audio.mp3");
  const bgSrc = path.join(songDir, "bg.jpg");

  const [lyricsRaw, themeRaw, energyRaw] = await Promise.all([
    fs.readFile(lyricsPath, "utf8").catch(() => null),
    fs.readFile(themePath, "utf8").catch(() => null),
    fs.readFile(energy ?? path.join(ROOT, "assets", "energy.json"), "utf8").catch(() => null),
  ]);

  if (!lyricsRaw) throw new Error(`Missing ${lyricsPath}`);
  if (!themeRaw) throw new Error(`Missing ${themePath}`);
  if (!energyRaw) throw new Error("Missing energy.json — run scripts/analyze-audio.mjs first");

  const lyrics = JSON.parse(lyricsRaw);
  const words = (Array.isArray(lyrics) ? lyrics : lyrics.words ?? [])
    .filter((w) => w && typeof w.text === "string")
    .filter((w) => !w.type || w.type === "word");

  const theme = mergeTheme(JSON.parse(themeRaw));
  const energyData = JSON.parse(energyRaw);

  const dur = Math.max(energyData.duration ?? 0, words.length ? words[words.length - 1].end + 3 : 0);

  const songId = path.basename(song);
  const seedStr = `${songId}:${theme.mood}:${theme.energy}`;
  const particles = buildParticles(theme, seedStr);
  const chunks = buildChunks(words);
  const chunkWin = chunkWindows(chunks, dur);

  await fs.mkdir(path.join(ROOT, "assets"), { recursive: true });
  await fs.mkdir(path.join(ROOT, "compositions"), { recursive: true });

  await Promise.all([
    fs.copyFile(audioSrc, path.join(ROOT, "assets", "audio.mp3")).catch((e) => {
      throw new Error(`Cannot copy audio.mp3: ${e.message}`);
    }),
    fs.copyFile(bgSrc, path.join(ROOT, "assets", "bg.jpg")).catch((e) => {
      throw new Error(`Cannot copy bg.jpg: ${e.message}`);
    }),
  ]);

  const indexHtml = renderIndex({ theme, dur, particles, energyData, songId });
  const lyricsHtml = renderLyrics({ theme, words, chunks, chunkWin, dur });

  await Promise.all([
    fs.writeFile(path.join(ROOT, "index.html"), indexHtml),
    fs.writeFile(path.join(ROOT, "compositions", "lyrics.html"), lyricsHtml),
    fs.writeFile(
      path.join(ROOT, "assets", "energy.json"),
      JSON.stringify(energyData),
    ),
    fs.writeFile(
      path.join(ROOT, "meta.json"),
      JSON.stringify(
        { name: songId, description: `AI-generated lyric video for ${songId}` },
        null,
        2,
      ),
    ),
  ]);

  console.log(
    `✓ built index.html + compositions/lyrics.html for "${songId}" ` +
      `(${words.length} words, ${chunks.length} chunks, ${particles.length} particles, ${dur.toFixed(2)}s)`,
  );
}

function renderIndex({ theme, dur, particles, energyData, songId }) {
  const t = theme.typography;
  const c = theme.colors;
  const bg = theme.background;
  const entrance = ENTRANCE[theme.animation.wordEntrance] ?? ENTRANCE["scale-pop"];

  const energyJson = JSON.stringify({
    bass: energyData.bass,
    mid: energyData.mid,
    high: energyData.high,
    sampleRate: energyData.sampleRate,
  });

  const particlesHtml = particles
    .map(
      (p) =>
        `<div class="particle" id="p-${p.i}" style="left:${p.x}px;top:${p.y}px;">` +
        `<span class="p-inner ${p.shapeClass} ${p.reactClass}" ` +
        `style="--psize:${p.size}px;--pcolor:${p.color};--phalo:${p.halo};--pglow:${p.glow}px;--po:${p.opacity};"></span></div>`,
    )
    .join("\n      ");

  const driftLines = particles
    .map((p) => {
      const base = `tl.to("#p-${p.i}",{x:${p.dx},y:${p.dy}`;
      const end = p.geometric ? `,rotation:${p.rot.toFixed(0)}` : "";
      return `${base}${end},duration:${dur.toFixed(3)},ease:"none"},0);`;
    })
    .join("\n        ");

  const overlayStart = hexToRgba(c.background, bg.overlayOpacity);
  const overlayEnd = hexToRgba(c.background, Math.min(1, bg.overlayOpacity + 0.15));
  const filter =
    `blur(${bg.blur}px) brightness(${bg.brightness}) saturate(${bg.saturation})`;
  const fontLink = googleFontLink(t.fontFamily, t.fontWeight);

  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Lyric Video — ${escCss(songId)}</title>
    ${fontLink}
    <script src="vendor/gsap.min.js"></script>
    <style>
      * { margin: 0; padding: 0; box-sizing: border-box; }
      html, body { width: ${WIDTH}px; height: ${HEIGHT}px; overflow: hidden; background: ${c.background}; }
      [data-composition-id="root"] {
        position: relative;
        width: ${WIDTH}px;
        height: ${HEIGHT}px;
        overflow: hidden;
        background: ${c.background};
      }
      #bg {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        will-change: transform;
      }
      #bg-overlay {
        position: absolute;
        inset: 0;
        background: linear-gradient(180deg, ${overlayStart} 0%, transparent 30%, transparent 70%, ${overlayEnd} 100%);
      }
      #particles { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
      .particle { position: absolute; width: 0; height: 0; will-change: transform; }
      .p-inner {
        position: absolute;
        left: 0; top: 0;
        width: var(--psize);
        height: var(--psize);
        margin-left: calc(var(--psize) / -2);
        margin-top: calc(var(--psize) / -2);
        background: var(--pcolor);
        border-radius: 50%;
      }
      .p-shape-spark { border-radius: 2px; box-shadow: 0 0 var(--pglow) var(--pcolor), 0 0 calc(var(--pglow) * 2.5) var(--phalo); }
      .p-shape-glow  { box-shadow: 0 0 var(--pglow) var(--pcolor), 0 0 calc(var(--pglow) * 3) var(--phalo); }
      .p-shape-bubble { background: transparent; border: 2px solid var(--pcolor); }
      .p-shape-wave {
        border-radius: 999px;
        width: calc(var(--psize) * 3);
        height: calc(var(--psize) * 0.55);
        margin-left: calc(var(--psize) * -1.5);
        margin-top: calc(var(--psize) * -0.275);
      }
      .p-shape-geometric { background: transparent; border: 2px solid var(--pcolor); border-radius: 2px; }
      .p-react-bass { transform: scale(calc(0.7 + var(--bass, 0) * 1.4)); opacity: calc(var(--po) * (0.35 + var(--mid, 0) * 0.6)); }
      .p-react-mid  { transform: scale(calc(0.8 + var(--mid, 0) * 0.9)); opacity: calc(var(--po) * (0.3 + var(--high, 0) * 0.55)); }
      .p-react-soft { transform: scale(calc(0.9 + var(--mid, 0) * 0.5)); opacity: calc(var(--po) * (0.35 + var(--high, 0) * 0.4)); }
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="root" data-start="0"
         data-width="${WIDTH}" data-height="${HEIGHT}" data-duration="${dur.toFixed(3)}">

      <img id="bg" class="clip" data-start="0" data-duration="${dur.toFixed(3)}"
           data-track-index="1" src="assets/bg.jpg" style="filter:${filter};" />
      <div id="bg-overlay" class="clip" data-start="0" data-duration="${dur.toFixed(3)}" data-track-index="2"></div>

      <div id="particles" class="clip" data-start="0" data-duration="${dur.toFixed(3)}" data-track-index="3">
      ${particlesHtml}
      </div>

      <div id="lyrics-host" data-composition-id="lyrics" data-composition-src="compositions/lyrics.html"
           data-start="0" data-track-index="4" style="position:absolute;inset:0;"></div>

      <audio id="music" data-start="0" data-duration="${dur.toFixed(3)}" data-track-index="0"
             data-volume="1" src="assets/audio.mp3"></audio>

      <script>
        (function () {
          var tl = gsap.timeline({ paused: true });

          // Ken Burns background
          tl.fromTo("#bg", { scale: 1 }, { scale: ${(1 + bg.zoomAmount).toFixed(4)}, ease: "none", duration: ${dur.toFixed(3)} }, 0);

          // Energy proxy: drive reactive CSS vars on the root (precomputed, seek-safe)
          var E = ${energyJson};
          var rate = E.sampleRate || 10;
          for (var i = 0; i < E.bass.length; i++) {
            tl.set("#root", {
              "--bass": E.bass[i],
              "--mid": E.mid[i],
              "--high": E.high[i]
            }, i / rate);
          }

          // Particle drift
        ${driftLines}

          // Extend the timeline to the full song duration
          tl.set({}, {}, ${dur.toFixed(3)});

          window.__timelines["root"] = tl;
        })();
      </script>
    </div>
  </body>
</html>
`;
}

function renderLyrics({ theme, words, chunks, chunkWin, dur }) {
  const t = theme.typography;
  const c = theme.colors;
  const entrance = ENTRANCE[theme.animation.wordEntrance] ?? ENTRANCE["scale-pop"];
  const entranceDur = 0.3;
  const gap = Math.round(t.letterSpacing * 2.5);

  const wordsJson = JSON.stringify(words);
  const chunkMeta = chunks.map((chunk, ci) => {
    const span = chunk.map((w) => w.text).join(" ");
    return {
      ci,
      start: +chunkWin[ci].start.toFixed(3),
      end: +chunkWin[ci].end.toFixed(3),
      wordIndexes: chunk.map((w) => words.indexOf(w)),
      preview: span.slice(0, 24),
    };
  });
  const chunkMetaJson = JSON.stringify(chunkMeta);

  const fontLink = googleFontLink(t.fontFamily, t.fontWeight);
  const activeGlow = (t.activeWordGlow ?? "").replace(/currentColor/g, c.accent);

  return `<template id="lyrics-template">
  <div data-composition-id="lyrics" data-width="${WIDTH}" data-height="${HEIGHT}">
    <style>
      [data-composition-id="lyrics"] {
        position: absolute;
        inset: 0;
        width: ${WIDTH}px;
        height: ${HEIGHT}px;
        overflow: hidden;
        pointer-events: none;
        font-family: ${t.fontFamily};
        font-size: ${t.fontSize}px;
        font-weight: ${t.fontWeight};
        letter-spacing: ${t.letterSpacing}px;
        line-height: ${t.lineHeight};
      }
      #lyrics-layer {
        position: absolute;
        inset: 0;
        display: flex;
        align-items: center;
        justify-content: center;
      }
      .lyric-chunk {
        position: absolute;
        left: 50%;
        top: 50%;
        opacity: 0;
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: center;
        gap: ${gap}px;
        max-width: 1700px;
        padding: 0 140px;
      }
      .lyric-word {
        display: inline-block;
        white-space: pre;
        opacity: 0;
        color: ${c.text};
        will-change: transform, opacity, text-shadow;
      }
    </style>
    <div id="lyrics-layer"></div>
    <script>
      (function () {
        var WORDS = ${wordsJson};
        var CHUNKS = ${chunkMetaJson};
        var cfg = {
          activeScale: ${t.activeWordScale},
          activeGlow: ${JSON.stringify(activeGlow)},
          textColor: ${JSON.stringify(c.text)},
          entranceEase: ${JSON.stringify(entrance.ease)},
          entranceY: ${entrance.y},
          entranceScale: ${entrance.scale},
          entranceDur: ${entranceDur}
        };

        var layer = document.getElementById("lyrics-layer");
        var tl = gsap.timeline({ paused: true });

        CHUNKS.forEach(function (chunk) {
          var div = document.createElement("div");
          div.className = "lyric-chunk";
          div.id = "chunk-" + chunk.ci;
          layer.appendChild(div);
          tl.set(div, { xPercent: -50, yPercent: -50 }, 0);

          chunk.wordIndexes.forEach(function (wi) {
            var word = WORDS[wi];
            var span = document.createElement("span");
            span.className = "lyric-word";
            span.id = "w-" + wi;
            span.textContent = word.text;
            div.appendChild(span);

            var dur = Math.max(0.08, Math.min(cfg.entranceDur, word.end - word.start - 0.05));
            var highlightAt = Math.min(word.start + dur, Math.max(word.start + 0.05, word.end - 0.1));

            tl.fromTo(
              span,
              { opacity: 0, y: cfg.entranceY, scale: cfg.entranceScale },
              { opacity: 0.35, y: 0, scale: 1, duration: dur, ease: cfg.entranceEase },
              word.start
            );
            tl.to(
              span,
              { opacity: 1, scale: cfg.activeScale, textShadow: cfg.activeGlow, duration: 0.12, ease: "power1.out" },
              highlightAt
            );
            tl.to(
              span,
              { opacity: 0.35, scale: 1, textShadow: "none", duration: 0.25, ease: "power1.out" },
              Math.min(word.end, chunk.end)
            );
          });

          tl.fromTo(
            div,
            { opacity: 0, y: 26 },
            { opacity: 1, y: 0, duration: 0.35, ease: "power2.out" },
            chunk.start
          );
          tl.to(div, { opacity: 0, y: -26, duration: 0.35, ease: "power2.in" }, chunk.end - 0.2);
        });

        tl.set({}, {}, ${dur.toFixed(3)});
        window.__timelines["lyrics"] = tl;
      })();
    </script>
  </div>
</template>
`;
}

main().catch((err) => {
  console.error("build-composition failed:", err.message);
  process.exit(1);
});
